import type { TutorialStep } from '../core/types';

// The Hard Way as a guided tutorial: every step is a command to run, with an explanation of what it does and why.
// The steps are also the reference solution of each lab (tests replay them, and later labs start from their result).

const step = (title: string, cmd: string, why: string): TutorialStep => ({ title, cmd, why });

/** The long one-shot command that prepares a worker node (used for node-1 after node-0 was done step by step). */
export const nodePrep = (host: string): string =>
  `ssh root@${host} "apt-get -y install socat conntrack ipset kmod; swapoff -a; mkdir -p /etc/cni/net.d /opt/cni/bin /var/lib/kubelet /var/lib/kube-proxy /var/lib/kubernetes /var/run/kubernetes; mv crictl kube-proxy kubelet runc /usr/local/bin/; mv containerd containerd-shim-runc-v2 containerd-stress /bin/; mv cni-plugins/* /opt/cni/bin/; mv 10-bridge.conf 99-loopback.conf /etc/cni/net.d/; modprobe br-netfilter; echo br-netfilter >> /etc/modules-load.d/modules.conf; echo 'net.bridge.bridge-nf-call-iptables = 1' >> /etc/sysctl.d/kubernetes.conf; echo 'net.bridge.bridge-nf-call-ip6tables = 1' >> /etc/sysctl.d/kubernetes.conf; sysctl -p /etc/sysctl.d/kubernetes.conf; mkdir -p /etc/containerd/; mv containerd-config.toml /etc/containerd/config.toml; mv containerd.service /etc/systemd/system/; mv kubelet-config.yaml /var/lib/kubelet/; mv kubelet.service /etc/systemd/system/; mv kube-proxy-config.yaml /var/lib/kube-proxy/; mv kube-proxy.service /etc/systemd/system/; systemctl daemon-reload; systemctl enable containerd kubelet kube-proxy; systemctl start containerd kubelet kube-proxy"`;

const kc = (file: string, user: string, crt: string, server: string): string[] => [
  `kubectl config set-cluster kubernetes-the-hard-way --certificate-authority=ca.crt --embed-certs=true --server=${server} --kubeconfig=${file}.kubeconfig`,
  `kubectl config set-credentials ${user} --client-certificate=${crt}.crt --client-key=${crt}.key --embed-certs=true --kubeconfig=${file}.kubeconfig`,
  `kubectl config set-context default --cluster=kubernetes-the-hard-way --user=${user} --kubeconfig=${file}.kubeconfig`,
  `kubectl config use-context default --kubeconfig=${file}.kubeconfig`,
];

const API = 'https://server.kubernetes.local:6443';

export const LABS: TutorialStep[][] = [
  // ------------------------------------------------------------------------------------------------------------ 1. jumpbox
  [
    step('Where am I?', 'pwd',
      'You are logged in as <code>root</code> on the <b>jumpbox</b>, in <code>/root</code>. The jumpbox is the one machine you work from: it holds the downloads, the certificate authority and the keys, and it reaches the other three machines over SSH. Nothing in this tutorial needs a graphical tool, only a shell, so everything you learn here is what an installer like kubeadm does for you behind the scenes.'),
    step('Get the guide', 'git clone --depth 1 https://github.com/kelseyhightower/kubernetes-the-hard-way.git',
      'This downloads Kelsey Hightower\'s repository. <code>--depth 1</code> fetches only the latest commit, which is all we need. It contains the ready-made files the tutorial uses (CA configuration, systemd unit files, component configs), so you do not have to write them by hand.'),
    step('Enter the repository', 'cd kubernetes-the-hard-way',
      'All following commands are run from inside this directory, so relative paths like <code>configs/</code> and <code>units/</code> work. Notice the prompt now shows where you are.'),
    step('Look around', 'ls',
      '<code>ca.conf</code> describes every certificate we will create, <code>configs/</code> and <code>units/</code> hold configuration and systemd unit files, <code>machines.txt</code> lists the machines, and <code>downloads-amd64.txt</code> lists everything to download. Keep this directory: all later labs start here.'),
    step('See what a cluster is made of', 'cat downloads-amd64.txt',
      'A Kubernetes cluster is just a handful of programs. <b>On the control plane:</b> <code>kube-apiserver</code>, <code>kube-controller-manager</code>, <code>kube-scheduler</code> and <code>etcd</code>. <b>On every worker:</b> <code>kubelet</code>, <code>kube-proxy</code>, the container runtime <code>containerd</code> with <code>runc</code>, <code>crictl</code> to inspect it, and the <b>CNI plugins</b> for pod networking. <b>For you:</b> <code>kubectl</code> (and <code>etcdctl</code>). Eleven files, all static binaries.'),
    step('Pick the CPU architecture', 'ARCH=$(dpkg --print-architecture)',
      'Binaries are built per CPU architecture (<code>amd64</code> or <code>arm64</code>). <code>dpkg --print-architecture</code> asks Debian which one this machine is, and <code>$(...)</code> stores the answer in the shell variable <code>ARCH</code>, so the next commands work on either kind of machine.'),
    step('Download everything', 'wget -q --show-progress --https-only --timestamping -P downloads -i downloads-${ARCH}.txt',
      '<code>-i</code> reads the list of URLs from the file; <code>-P downloads</code> saves them into <code>downloads/</code>; <code>--https-only</code> refuses plain HTTP so nobody can tamper with a binary in transit; <code>--timestamping</code> skips files you already have; <code>-q --show-progress</code> keeps the output short.'),
    step('Check the download', 'ls -loh downloads',
      '<code>-l</code> long format, <code>-h</code> human sizes. Notice the file modes: they start with <code>-rw-</code>, so none of these programs is <b>executable</b> yet. You will fix that in a moment.'),
    step('Sort the files by role', 'mkdir -p downloads/{client,cni-plugins,controller,worker}',
      'Different machines need different files, so we sort them now. <code>{a,b,c}</code> is <b>brace expansion</b>: the shell expands it into four directory names. <code>-p</code> creates parents and does not complain if they exist. <code>client</code> is for tools you use, <code>controller</code> for the control plane, <code>worker</code> for nodes.'),
    step('Unpack crictl', 'tar -xvf downloads/crictl-v1.32.0-linux-${ARCH}.tar.gz -C downloads/worker/ crictl',
      '<code>crictl</code> is a CLI for the container runtime, used to debug containers on a node. <code>tar -xvf</code> = e<b>x</b>tract, <b>v</b>erbose, from <b>f</b>ile; <code>-C</code> says where to extract to; the final word <code>crictl</code> extracts only that member of the archive.'),
    step('Unpack containerd', 'tar -xvf downloads/containerd-2.1.0-beta.0-linux-${ARCH}.tar.gz --strip-components 1 -C downloads/worker/',
      '<b>containerd</b> is the container runtime: it pulls images and manages containers on behalf of the kubelet. The archive stores files as <code>bin/containerd</code>; <code>--strip-components 1</code> drops the leading <code>bin/</code> so the files land directly in <code>worker/</code>.'),
    step('Unpack the CNI plugins', 'tar -xvf downloads/cni-plugins-linux-${ARCH}-v1.6.2.tgz -C downloads/cni-plugins/',
      'CNI (Container Network Interface) plugins are small programs the runtime calls to give a pod a network interface and an IP address. <code>bridge</code> will connect pods on a node, <code>host-local</code> hands out the IPs, <code>loopback</code> creates <code>lo</code>.'),
    step('Unpack etcd', 'tar -xvf downloads/etcd-v3.6.0-rc.3-linux-${ARCH}.tar.gz -C downloads/ --strip-components 1 etcd-v3.6.0-rc.3-linux-${ARCH}/etcdctl etcd-v3.6.0-rc.3-linux-${ARCH}/etcd',
      '<b>etcd</b> is the cluster\'s database; <code>etcdctl</code> is its CLI. We extract only these two members, and strip the top directory name so they land in <code>downloads/</code>.'),
    step('Move the client tools', 'mv downloads/{etcdctl,kubectl} downloads/client/',
      'Now every binary is in <code>downloads/</code> and we file it where it will be used. <code>mv downloads/{etcdctl,kubectl}</code> expands to two source paths, the last argument is the destination directory.'),
    step('Move the control plane binaries', 'mv downloads/{etcd,kube-apiserver,kube-controller-manager,kube-scheduler} downloads/controller/',
      'These four run only on the <code>server</code> machine. Keeping them in their own folder makes copying them later a one-liner.'),
    step('Move the worker binaries', 'mv downloads/{kubelet,kube-proxy} downloads/worker/',
      '<code>kubelet</code> is the agent that runs pods on a node, <code>kube-proxy</code> programs the node\'s iptables so Services work.'),
    step('Rename runc', 'mv downloads/runc.${ARCH} downloads/worker/runc',
      '<b>runc</b> is the low-level tool that actually creates a container (namespaces, cgroups). containerd calls it. The download is named for its architecture; everyone just calls it <code>runc</code>, so we rename it while moving it.'),
    step('Make them executable', 'chmod +x downloads/{client,cni-plugins,controller,worker}/*',
      'Linux only runs a file if its <b>execute bit</b> is set. <code>chmod +x</code> sets it. The pattern uses brace expansion for the four directories and a <b>glob</b> <code>*</code> for "every file inside". Try <code>ls -l downloads/worker</code> afterwards: the modes now start with <code>-rwx</code>.'),
    step('Check the result', 'ls -l downloads/worker',
      'The execute bits are set. Anything in <code>downloads/</code> that is not in a subfolder is an archive you no longer need.'),
    step('Install kubectl', 'cp downloads/client/kubectl /usr/local/bin/',
      '<code>/usr/local/bin</code> is on the shell\'s <code>PATH</code>, so a program there can be run by name. <code>kubectl</code> is your remote control for the cluster: it turns commands into calls to the API server.'),
    step('Verify', 'kubectl version --client',
      'You should see <b>Client Version: v1.32.3</b>. There is no server yet, so <code>--client</code> asks only for the local version. If it says <i>Permission denied</i> the execute bit was missing; if <i>command not found</i> the copy failed.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 2. compute
  [
    step('Read the machine inventory', 'cat machines.txt',
      'One line per machine: <b>IP, FQDN, hostname</b> and, for workers, the <b>pod subnet</b> that node will hand out to its pods (<code>10.200.0.0/24</code> and <code>10.200.1.0/24</code>; they must not overlap). In the real guide you fill this in with your own cloud machines. Everything below reads this file instead of hard-coding values.'),
    step('Create an SSH key pair', 'ssh-keygen',
      'You will run dozens of commands on the other machines. Typing a password every time is painful and insecure, so you create an <b>SSH key pair</b>: a private key that stays on the jumpbox and a public key that you install on the machines you want to reach.'),
    step('Install the key on every machine', 'while read IP FQDN HOST SUBNET; do ssh-copy-id root@${IP}; done < machines.txt',
      '<code>while read A B C D; do ...; done &lt; file</code> reads the file line by line and splits each line into the named variables. For each machine <code>ssh-copy-id</code> appends your public key to <code>~/.ssh/authorized_keys</code> there. (We use the IP because names are not set up yet.)'),
    step('First look at a machine', 'ssh -n root@10.240.0.10 hostname',
      '<code>ssh user@host command</code> runs one command remotely and prints the output. <code>-n</code> stops ssh from reading your terminal input, which matters inside loops. The answer is <b>debian</b>: a fresh machine has a generic name. Kubernetes will use the hostname as the <b>node name</b>, so it must be right.'),
    step('Set the hostnames and local DNS entry', `while read IP FQDN HOST SUBNET; do CMD="sed -i 's/^127.0.1.1.*/127.0.1.1\\t\${FQDN} \${HOST}/' /etc/hosts"; ssh -n root@\${IP} "$CMD"; ssh -n root@\${IP} hostnamectl set-hostname \${HOST}; ssh -n root@\${IP} systemctl restart systemd-hostnamed; done < machines.txt`,
      'For each machine, three remote actions: (1) <code>sed -i</code> rewrites the <code>127.0.1.1</code> line of <code>/etc/hosts</code> so the machine resolves its own name; (2) <code>hostnamectl set-hostname</code> sets the real hostname (<code>server</code>, <code>node-0</code>, <code>node-1</code>); (3) restarting <code>systemd-hostnamed</code> makes the change visible at once.'),
    step('Verify the hostnames', 'while read IP FQDN HOST SUBNET; do ssh -n root@${IP} hostname; done < machines.txt',
      'You should see <b>server, node-0, node-1</b>. The little diagram above the terminal shows the same.'),
    step('Start a hosts file', 'echo "" > hosts',
      'Now every machine has to resolve every other machine by name. We build one shared <b>hosts</b> file. <code>&gt;</code> redirects output into a file, creating or <i>overwriting</i> it, so this makes an empty file.'),
    step('Add a comment', 'echo "# Kubernetes The Hard Way" >> hosts',
      '<code>&gt;&gt;</code> <i>appends</i> instead of overwriting. Keeping a comment line makes it obvious where this block starts in <code>/etc/hosts</code>.'),
    step('Add one line per machine', 'while read IP FQDN HOST SUBNET; do ENTRY="${IP} ${FQDN} ${HOST}"; echo $ENTRY >> hosts; done < machines.txt',
      'The format of <code>/etc/hosts</code> is <code>IP  fully.qualified.name  shortname</code>. The loop builds that line from the three fields of each machine and appends it.'),
    step('Check the file', 'cat hosts',
      'Three entries, for <code>server.kubernetes.local</code>, <code>node-0.kubernetes.local</code> and <code>node-1.kubernetes.local</code>. Later the API server certificate will list <code>server.kubernetes.local</code>, which is why this exact name matters.'),
    step('Use it on the jumpbox', 'cat hosts >> /etc/hosts',
      'The jumpbox itself must resolve the names too (you will call the API server by name from here).'),
    step('Distribute it', 'while read IP FQDN HOST SUBNET; do scp hosts root@${HOST}:~/; ssh -n root@${HOST} "cat hosts >> /etc/hosts"; done < machines.txt',
      '<code>scp</code> copies a file over SSH; <code>~/</code> is the remote home directory. Then the same <code>cat hosts &gt;&gt; /etc/hosts</code> runs on each machine. Notice that now we can say <code>root@node-0</code>: the name resolves.'),
    step('Test name resolution', 'ssh -n root@node-0 cat /etc/hosts',
      'The remote machine\'s hosts file contains all three entries. From now on every command can use names like <code>server</code> and <code>node-1</code> instead of IP addresses.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 3. certificates
  [
    step('Read the certificate plan', 'cat ca.conf',
      'This OpenSSL configuration describes <b>eight identities</b>. For each: a <code>CN</code> (common name = the Kubernetes <b>user name</b>) and often an <code>O</code> (organisation = the <b>group</b>). For example <code>admin</code> is in group <code>system:masters</code> (cluster-admin), nodes are <code>system:node:node-0</code> in <code>system:nodes</code>. The API server section also lists <b>Subject Alternative Names</b>: every name and IP clients may use to reach it.'),
    step('Create the CA private key', 'openssl genrsa -out ca.key 4096',
      'Everything is trusted because of one <b>certificate authority</b> (CA). Its <b>private key</b> signs certificates, so guard it. <code>genrsa</code> generates a 4096-bit RSA key.'),
    step('Create the CA certificate', 'openssl req -x509 -new -sha512 -noenc -key ca.key -days 3653 -config ca.conf -out ca.crt',
      '<code>-x509</code> makes a <b>self-signed</b> certificate (the CA vouches for itself), valid for ten years (<code>-days 3653</code>). <code>-noenc</code> leaves the key unencrypted. Everybody in the cluster will be given this <code>ca.crt</code> as the thing to trust.'),
    step('Inspect the CA', 'openssl x509 -in ca.crt -noout -text',
      'Read it: the <b>Issuer</b> and <b>Subject</b> are the same (self-signed) and <code>CA:TRUE</code> says it may sign other certificates.'),
    step('Admin: generate a key', 'openssl genrsa -out admin.key 4096',
      'Now the same recipe for each identity, three commands each. First the identity\'s own private key. We do <code>admin</code> by hand so you see every step, then loop over the rest.'),
    step('Admin: create a signing request', 'openssl req -new -key admin.key -sha256 -config ca.conf -section admin -out admin.csr',
      'A <b>CSR</b> (certificate signing request) says "here is my public key and the identity I claim". <code>-section admin</code> picks the <code>[admin]</code> part of <code>ca.conf</code>, which holds the CN and O.'),
    step('Admin: have the CA sign it', 'openssl x509 -req -days 3653 -in admin.csr -copy_extensions copyall -sha256 -CA ca.crt -CAkey ca.key -CAcreateserial -out admin.crt',
      'The CA signs the CSR and produces <code>admin.crt</code>. <code>-copy_extensions copyall</code> carries the requested extensions (the SAN list) over: without it the certificate would have no names. <code>-CAcreateserial</code> creates the serial number file the first time.'),
    step('Inspect the admin certificate', 'openssl x509 -in admin.crt -noout -text',
      'Find <b>Subject: O = system:masters, CN = admin</b>. This is how Kubernetes will know you: no password, your certificate says who you are and the group gives you the power. Issuer is your CA.'),
    step('All the other identities', 'for i in node-0 node-1 kube-proxy kube-scheduler kube-controller-manager kube-api-server service-accounts; do openssl genrsa -out "${i}.key" 4096; openssl req -new -key "${i}.key" -sha256 -config "ca.conf" -section ${i} -out "${i}.csr"; openssl x509 -req -days 3653 -in "${i}.csr" -copy_extensions copyall -sha256 -CA "ca.crt" -CAkey "ca.key" -CAcreateserial -out "${i}.crt"; done',
      'A <code>for</code> loop runs the same three commands for the remaining seven identities: the two kubelets, kube-proxy, the scheduler, the controller manager, the API server, and <code>service-accounts</code> (whose key signs the tokens pods use to call the API).'),
    step('Inspect the API server certificate', 'openssl x509 -in kube-api-server.crt -noout -text',
      'The important part is <b>Subject Alternative Name</b>: <code>server.kubernetes.local</code>, <code>kubernetes</code>, <code>kubernetes.default.svc...</code>, <code>127.0.0.1</code> and <code>10.32.0.1</code> (the in-cluster address of the API). A client refuses to connect if the name it dialled is not in this list: <i>"x509: certificate is valid for ..., not ..."</i>. That is why we passed <code>-copy_extensions copyall</code>.'),
    step('See what you made', 'ls *.crt',
      'Nine certificates: the CA plus eight identities (and the matching <code>.key</code> and <code>.csr</code> files). Next lab: put each one where it is used.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 4. distribute
  [
    step('Prepare node-0', 'ssh root@node-0 mkdir /var/lib/kubelet/',
      'The kubelet looks for its credentials in <code>/var/lib/kubelet</code>. First create that directory on <code>node-0</code> with a one-shot remote command. Only the files a machine needs should ever be copied to it; every extra private key is extra risk.'),
    step('node-0: the CA certificate', 'scp ca.crt root@node-0:/var/lib/kubelet/',
      'The kubelet needs <code>ca.crt</code> to verify the API server it connects to (and to verify clients that call the kubelet). A trailing <code>/</code> says "copy into this directory".'),
    step('node-0: its own certificate', 'scp node-0.crt root@node-0:/var/lib/kubelet/kubelet.crt',
      'This is node-0\'s identity, <code>system:node:node-0</code>. It is renamed to <code>kubelet.crt</code> because that is the file name the kubelet configuration expects. <b>Each node gets its own certificate</b>: the <i>Node authorizer</i> only lets a kubelet touch its own node and pods, so node-1\'s certificate would not work here.'),
    step('node-0: its private key', 'scp node-0.key root@node-0:/var/lib/kubelet/kubelet.key',
      'The matching private key. It never leaves the machine that needs it, apart from this one copy.'),
    step('node-1: the same, in a loop', 'for host in node-1; do ssh root@${host} mkdir /var/lib/kubelet/; scp ca.crt root@${host}:/var/lib/kubelet/; scp ${host}.crt root@${host}:/var/lib/kubelet/kubelet.crt; scp ${host}.key root@${host}:/var/lib/kubelet/kubelet.key; done',
      'The four commands above, generalised with <code>${host}</code>. (With two nodes you could have looped from the start; with fifty you would. The guide does <code>for host in node-0 node-1</code>.)'),
    step('The control plane gets its files', 'scp ca.key ca.crt kube-api-server.key kube-api-server.crt service-accounts.key service-accounts.crt root@server:~/',
      'The server needs: the CA pair (the controller manager signs certificate requests with <code>ca.key</code>), the API server\'s own pair, and the service-account pair. Note that the nodes got <b>no</b> <code>ca.key</code>: a node must never be able to mint new identities.'),
    step('Check a node', 'ssh root@node-0 ls /var/lib/kubelet',
      'Three files: <code>ca.crt</code>, <code>kubelet.crt</code>, <code>kubelet.key</code>. The diagram above ticks "kubelet certificate" for both nodes.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 5. kubeconfigs
  [
    step('What a kubeconfig is', 'ls *.crt',
      'Certificates alone are not enough: a client also has to know <b>which server</b> to talk to. A <b>kubeconfig</b> bundles three things: a <i>cluster</i> (server URL + CA), a <i>user</i> (client certificate and key) and a <i>context</i> (which user with which cluster). You build one with four <code>kubectl config</code> commands. We do <code>node-0</code> step by step.'),
    ...kc('node-0', 'system:node:node-0', 'node-0', API).map((cmd, i) => step(
      ['node-0: add the cluster', 'node-0: add the credentials', 'node-0: create the context', 'node-0: select the context'][i], cmd,
      [
        '<code>set-cluster</code> records the API server address and embeds the CA certificate. <code>--embed-certs=true</code> copies the certificate <i>data</i> into the file instead of a path, so the file keeps working after being copied to another machine. <code>--kubeconfig=</code> says which file to write.',
        '<code>set-credentials</code> stores the client certificate and key. The user name <code>system:node:node-0</code> is a label in this file; Kubernetes itself takes your identity from the certificate\'s CN.',
        '<code>set-context</code> joins a cluster and a user under a name (<code>default</code>).',
        '<code>use-context</code> makes it the current context. Without it kubectl would not know which one to use.',
      ][i])),
    step('Read the result', 'cat node-0.kubeconfig',
      'A small YAML file: <code>clusters</code>, <code>users</code> (with <code>client-certificate-data</code>: your certificate, inline), <code>contexts</code> and <code>current-context</code>. This is what the kubelet on node-0 will read to connect to the API server.'),
    step('node-1: same recipe', `for host in node-1; do ${kc('${host}', 'system:node:${host}', '${host}', API).join('; ')}; done`,
      'The identical four commands, parameterised with <code>${host}</code>.'),
    step('The three control plane clients', `for comp in kube-proxy kube-controller-manager kube-scheduler; do ${kc('${comp}', 'system:${comp}', '${comp}', API).join('; ')}; done`,
      'Each component has its own identity and kubeconfig: <b>kube-proxy</b> (watches Services on the nodes), <b>kube-controller-manager</b> and <b>kube-scheduler</b>. They reach the API at <code>server.kubernetes.local:6443</code>.'),
    step('Your own admin kubeconfig', kc('admin', 'admin', 'admin', 'https://127.0.0.1:6443').join('; '),
      'Same four commands for <code>admin</code>, but with <code>--server=https://127.0.0.1:6443</code>: this file will be used <i>on the server itself</i>, where the API server listens on localhost.'),
    step('Install the worker kubeconfigs', 'for host in node-0 node-1; do ssh root@${host} "mkdir -p /var/lib/{kube-proxy,kubelet}"; scp kube-proxy.kubeconfig root@${host}:/var/lib/kube-proxy/kubeconfig; scp ${host}.kubeconfig root@${host}:/var/lib/kubelet/kubeconfig; done',
      'Each worker gets two: the shared kube-proxy kubeconfig and <b>its own</b> kubelet kubeconfig (renamed to <code>kubeconfig</code>, the name the component configs expect). The quoted braces in the ssh command are expanded on the <i>remote</i> machine.'),
    step('Install the server kubeconfigs', 'scp admin.kubeconfig kube-controller-manager.kubeconfig kube-scheduler.kubeconfig root@server:~/',
      'The control plane gets the admin, controller manager and scheduler kubeconfigs. Check the diagram: the server and both nodes now have what they need to authenticate.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 6. encryption
  [
    step('Why encrypt', 'cat configs/encryption-config.yaml',
      'By default a Kubernetes <b>Secret</b> is only base64-encoded inside etcd: anyone who can read the database (or a backup) reads your passwords. This <code>EncryptionConfiguration</code> tells the API server to encrypt Secrets with <b>AES-CBC</b> before writing them. The key placeholder <code>${ENCRYPTION_KEY}</code> still needs a value. The last provider, <code>identity</code>, lets the API server still read old unencrypted data.'),
    step('Generate random bytes', 'head -c 32 /dev/urandom | base64',
      '<code>/dev/urandom</code> is the kernel\'s random source; <code>head -c 32</code> takes 32 bytes (256 bits, the AES-256 key size); <code>base64</code> turns them into printable text. A <code>|</code> pipe connects the output of one command to the input of the next.'),
    step('Keep the key in a variable', 'export ENCRYPTION_KEY=$(head -c 32 /dev/urandom | base64)',
      'Same command, but captured with <code>$(...)</code> into an <b>environment variable</b>. <code>export</code> makes it visible to programs started from this shell, which the next command needs.'),
    step('Check it is set', 'echo $ENCRYPTION_KEY',
      'You should see a 44-character string. If this prints an empty line the next step would silently produce a broken config and the API server would later refuse to start.'),
    step('Fill in the template', 'envsubst < configs/encryption-config.yaml > encryption-config.yaml',
      '<code>envsubst</code> replaces <code>${NAME}</code> in its input with environment variables. <code>&lt;</code> feeds the template in, <code>&gt;</code> writes the result to a new file.'),
    step('Read the result', 'cat encryption-config.yaml',
      'The <code>secret:</code> line now carries your key. Whoever has this file can decrypt your Secrets, so it goes only to the control plane.'),
    step('Send it to the server', 'scp encryption-config.yaml root@server:~/',
      'Later the API server unit will point at it with <code>--encryption-provider-config</code>. In the smoke test you will look into etcd and see whether it works.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 7. etcd
  [
    step('Read the unit file', 'cat units/etcd.service',
      'A <b>systemd unit</b> describes a service. <code>[Service] ExecStart=</code> is the command (here <code>/usr/local/bin/etcd</code> with its flags: a single-member cluster named <code>controller</code>, listening on <code>127.0.0.1:2379</code> for clients, data in <code>/var/lib/etcd</code>); <code>Restart=on-failure</code> brings it back after a crash; <code>WantedBy=multi-user.target</code> makes it start at boot once enabled.'),
    step('Copy etcd to the server', 'scp downloads/controller/etcd downloads/client/etcdctl units/etcd.service root@server:~/',
      'The server and etcd binary, the CLI, and the unit file travel together into the server\'s home directory.'),
    step('Log in to the server', 'ssh root@server',
      'Without a command, <code>ssh</code> opens an interactive session. Look at the prompt (<code>root@server:~#</code>) and the highlighted machine in the diagram: from here every command runs on the server.'),
    step('Install the binaries', 'mv etcd etcdctl /usr/local/bin/',
      'Put them on the <code>PATH</code>. The unit file expects <code>/usr/local/bin/etcd</code>; if it is missing, systemd fails with <i>status=203/EXEC</i>.'),
    step('Create the directories', 'mkdir -p /etc/etcd /var/lib/etcd',
      '<code>/etc/etcd</code> is for configuration, <code>/var/lib/etcd</code> for the <b>data directory</b> where etcd keeps the whole cluster state.'),
    step('Protect the data', 'chmod 700 /var/lib/etcd',
      'Mode 700 means only <code>root</code> can read it. Remember: this directory holds every object in the cluster, including (encrypted or not) Secrets.'),
    step('Copy the certificates', 'cp ca.crt kube-api-server.key kube-api-server.crt /etc/etcd/',
      'The guide places the CA and API server certificate next to etcd. In this simple setup etcd listens on localhost over plain HTTP so they are not used, but this is where they would be for a TLS-protected, multi-node etcd.'),
    step('Install the unit', 'mv etcd.service /etc/systemd/system/',
      '<code>/etc/systemd/system/</code> is where administrator-provided units live.'),
    step('Make systemd notice', 'systemctl daemon-reload',
      'systemd reads unit files into memory. After adding or editing one you must <b>reload</b>, otherwise <code>systemctl start</code> answers <i>Unit not found</i>.'),
    step('Start it at boot', 'systemctl enable etcd',
      '<code>enable</code> creates the symlink that starts the service on every boot. It does not start it now.'),
    step('Start it now', 'systemctl start etcd',
      '<code>start</code> runs it. If it fails, the error output tells you to look at <code>systemctl status etcd</code> and <code>journalctl -u etcd</code>: always do that.'),
    step('Check the service', 'systemctl status etcd',
      '<b>Active: active (running)</b> is what you want.'),
    step('Ask etcd who is in the cluster', 'etcdctl member list',
      'One member called <code>controller</code>. If etcd were not running this would fail with <i>context deadline exceeded</i>.'),
    step('Return to the jumpbox', 'exit',
      '<code>exit</code> ends the SSH session and drops you back on the jumpbox.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 8. control plane
  [
    step('Read a unit: the API server', 'cat units/kube-apiserver.service',
      'The flags are a map of what the API server needs and where it expects it: <code>--etcd-servers</code> (the database), <code>--client-ca-file</code> (which CA to trust for client certificates), <code>--tls-cert-file/--tls-private-key-file</code> (its own identity), <code>--encryption-provider-config</code>, <code>--service-account-key-file</code>, <code>--authorization-mode=Node,RBAC</code> and <code>--kubelet-client-certificate</code> (for when the API server calls a kubelet). Everything lives under <code>/var/lib/kubernetes/</code>.'),
    step('Copy everything to the server', 'scp downloads/controller/kube-apiserver downloads/controller/kube-controller-manager downloads/controller/kube-scheduler downloads/client/kubectl units/kube-apiserver.service units/kube-controller-manager.service units/kube-scheduler.service configs/kube-scheduler.yaml configs/kube-apiserver-to-kubelet.yaml root@server:~/',
      'Three control plane binaries, <code>kubectl</code>, their three unit files, the scheduler\'s configuration, and an RBAC manifest you will apply later.'),
    step('Log in to the server', 'ssh root@server', 'The next commands run on the control plane machine.'),
    step('Install the binaries', 'mv kube-apiserver kube-controller-manager kube-scheduler kubectl /usr/local/bin/',
      'All four programs onto the <code>PATH</code>.'),
    step('Create the config directories', 'mkdir -p /etc/kubernetes/config',
      'The scheduler\'s configuration file goes here.'),
    step('Create the data directory', 'mkdir -p /var/lib/kubernetes/',
      'All certificates, keys and kubeconfigs used by the control plane live here: it is the one place the units point to.'),
    step('Move the PKI and encryption config', 'mv ca.crt ca.key kube-api-server.key kube-api-server.crt service-accounts.key service-accounts.crt encryption-config.yaml /var/lib/kubernetes/',
      'The API server needs the CA, its own key pair, the service-account pair and the encryption config. The controller manager also uses <code>ca.key</code> to sign certificates and <code>service-accounts.key</code> to sign pod tokens.'),
    step('Install the API server unit', 'mv kube-apiserver.service /etc/systemd/system/kube-apiserver.service',
      'The unit file in its place.'),
    step('Controller manager: kubeconfig and unit', 'mv kube-controller-manager.kubeconfig /var/lib/kubernetes/ && mv kube-controller-manager.service /etc/systemd/system/',
      'The controller manager runs the <b>control loops</b>: it notices that a Deployment wants 3 replicas and creates the ReplicaSet and pods. It authenticates to the API server with this kubeconfig. (<code>&amp;&amp;</code> runs the second command only if the first succeeded.)'),
    step('Scheduler: kubeconfig, config and unit', 'mv kube-scheduler.kubeconfig /var/lib/kubernetes/ && mv kube-scheduler.yaml /etc/kubernetes/config/ && mv kube-scheduler.service /etc/systemd/system/',
      'The <b>scheduler</b> watches for pods without a node and assigns each to a node that fits. Its configuration file tells it which kubeconfig to use and enables leader election.'),
    step('Reload systemd', 'systemctl daemon-reload', 'Three new unit files to learn about.'),
    step('Enable the services', 'systemctl enable kube-apiserver kube-controller-manager kube-scheduler',
      'Start at boot. You can pass several services to one systemctl command.'),
    step('Start the services', 'systemctl start kube-apiserver kube-controller-manager kube-scheduler',
      'Order matters and the simulation checks it: the API server needs etcd (running since lab 7) and its files; the controller manager and scheduler need the API server. If one fails, <code>systemctl status</code> and <code>journalctl -u NAME</code> name the missing file or dependency.'),
    step('Ask the API server about itself', 'kubectl cluster-info --kubeconfig admin.kubeconfig',
      'Your first real kubectl command against your own cluster. <code>--kubeconfig</code> points at the admin file you made in lab 5 (it connects to <code>127.0.0.1:6443</code>).'),
    step('Let the API server talk to kubelets', 'kubectl apply -f kube-apiserver-to-kubelet.yaml --kubeconfig admin.kubeconfig',
      'When you run <code>kubectl logs</code> or <code>exec</code>, the API server connects <i>to the kubelet</i>. The kubelet uses <b>Webhook authorization</b> and denies it unless <b>RBAC</b> allows it. This manifest creates a ClusterRole for <code>nodes/proxy, nodes/log, nodes/stats...</code> and binds it to the API server\'s user <code>kubernetes</code>. Without it logs and exec fail later with "Forbidden".'),
    step('Back to the jumpbox', 'exit', 'Leave the server.'),
    step('Call the API from outside', 'curl --cacert ca.crt https://server.kubernetes.local:6443/version',
      'A plain HTTPS request. <code>--cacert ca.crt</code> tells curl which CA to trust (it does not know yours); without it curl rightly refuses with <i>SSL certificate problem</i>. The reply is the server version: the control plane is alive.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 9. workers
  [
    step('Why the config depends on the node', 'cat configs/10-bridge.conf',
      'The CNI <code>bridge</code> plugin needs the <b>pod subnet</b> of the node: <code>"subnet": "SUBNET"</code> is a placeholder. node-0 will hand out <code>10.200.0.x</code> addresses to its pods, node-1 <code>10.200.1.x</code>. We fill in the right value per node with <code>sed</code>, reading it from <code>machines.txt</code>.'),
    step('Generate per-node configs', 'for HOST in node-0 node-1; do SUBNET=$(grep ${HOST} machines.txt | cut -d " " -f 4); sed "s|SUBNET|$SUBNET|g" configs/10-bridge.conf > 10-bridge.conf; sed "s|SUBNET|$SUBNET|g" configs/kubelet-config.yaml > kubelet-config.yaml; scp 10-bridge.conf kubelet-config.yaml root@${HOST}:~/; done',
      '<code>grep HOST machines.txt</code> finds the node\'s line, <code>cut -d " " -f 4</code> takes the 4th space-separated field (its subnet). <code>sed "s|SUBNET|value|g"</code> substitutes the placeholder (<code>|</code> is the delimiter because the value contains <code>/</code>). The result is copied to the node. The kubelet config uses the same subnet as <code>podCIDR</code>.'),
    step('Ship the worker files', 'for HOST in node-0 node-1; do scp downloads/worker/* downloads/client/kubectl configs/99-loopback.conf configs/containerd-config.toml configs/kube-proxy-config.yaml units/containerd.service units/kubelet.service units/kube-proxy.service root@${HOST}:~/; done',
      'Everything a worker runs: <code>kubelet</code>, <code>kube-proxy</code>, containerd and its shim, <code>runc</code>, <code>crictl</code>, plus configuration and the three unit files.'),
    step('Ship the CNI plugins', 'for HOST in node-0 node-1; do scp downloads/cni-plugins/* root@${HOST}:~/cni-plugins/; done',
      'The network plugins go into their own directory first (they move to <code>/opt/cni/bin</code> in a moment).'),
    step('Log in to node-0', 'ssh root@node-0', 'We configure node-0 by hand, then do node-1 in one command.'),
    step('Install required packages', 'apt-get -y install socat conntrack ipset kmod',
      '<b>socat</b> is used by <code>kubectl port-forward</code>; <b>conntrack</b> and <b>ipset</b> are needed by kube-proxy for connection tracking and iptables sets; <b>kmod</b> provides <code>modprobe</code>. Skip one and the matching feature (or service) fails later.'),
    step('Disable swap', 'swapoff -a',
      'Kubernetes assumes memory limits are real. With swap the kernel could quietly move a container\'s memory to disk, so the kubelet <b>refuses to start while swap is on</b>. (Try <code>swapon --show</code> first to see it.) On a real machine you would also remove the swap entry from <code>/etc/fstab</code> to make it permanent.'),
    step('Create the directories', 'mkdir -p /etc/cni/net.d /opt/cni/bin /var/lib/kubelet /var/lib/kube-proxy /var/lib/kubernetes /var/run/kubernetes',
      'Standard locations: CNI configuration (<code>/etc/cni/net.d</code>) and plugin binaries (<code>/opt/cni/bin</code>), kubelet and kube-proxy state, and the Kubernetes run directory.'),
    step('Install the node programs', 'mv crictl kube-proxy kubelet runc /usr/local/bin/', 'Four programs onto the <code>PATH</code>.'),
    step('Install containerd', 'mv containerd containerd-shim-runc-v2 containerd-stress /bin/', 'containerd goes in <code>/bin</code>, which is where its unit file looks for it.'),
    step('Install the CNI plugins', 'mv cni-plugins/* /opt/cni/bin/', 'The runtime looks for plugins in <code>/opt/cni/bin</code>.'),
    step('Install the CNI configuration', 'mv 10-bridge.conf 99-loopback.conf /etc/cni/net.d/',
      'Files in <code>/etc/cni/net.d</code> are read in order. <code>10-bridge</code> attaches pods to a Linux bridge and allocates an IP from this node\'s subnet; <code>99-loopback</code> gives each pod a <code>lo</code> interface.'),
    step('Load the bridge netfilter module', 'modprobe br-netfilter',
      'Pods are connected to a bridge. This kernel module makes bridged traffic pass through <b>iptables</b>, which kube-proxy relies on to implement Services.'),
    step('Load it at every boot', 'echo br-netfilter >> /etc/modules-load.d/modules.conf', 'A file in <code>modules-load.d</code> is read at boot.'),
    step('Enable bridge filtering (IPv4)', "echo 'net.bridge.bridge-nf-call-iptables = 1' >> /etc/sysctl.d/kubernetes.conf", 'A kernel setting (<b>sysctl</b>) that turns the previous module on for IPv4 traffic. Single quotes keep the text exactly as typed.'),
    step('Enable bridge filtering (IPv6)', "echo 'net.bridge.bridge-nf-call-ip6tables = 1' >> /etc/sysctl.d/kubernetes.conf", 'The same for IPv6.'),
    step('Apply the settings', 'sysctl -p /etc/sysctl.d/kubernetes.conf', '<code>sysctl -p FILE</code> loads the settings now (they are also loaded at boot).'),
    step('Install the containerd configuration', 'mkdir -p /etc/containerd/ && mv containerd-config.toml /etc/containerd/config.toml',
      'The config selects the <code>overlayfs</code> snapshotter, <code>runc</code> as the runtime and tells containerd where the CNI plugins and configuration are.'),
    step('Install the containerd unit', 'mv containerd.service /etc/systemd/system/', 'Note this unit has no dependencies on Kubernetes: containerd could run on its own.'),
    step('Install the kubelet configuration and unit', 'mv kubelet-config.yaml /var/lib/kubelet/ && mv kubelet.service /etc/systemd/system/',
      'The <b>kubelet</b> is the node agent: it registers the node, watches the API server for pods assigned to it and tells containerd to run them. Its configuration holds the pod CIDR, the cluster DNS address and where its TLS certificate is. The unit says it needs containerd first.'),
    step('Install the kube-proxy configuration and unit', 'mv kube-proxy-config.yaml /var/lib/kube-proxy/ && mv kube-proxy.service /etc/systemd/system/',
      '<b>kube-proxy</b> watches Services and Endpoints and writes the <b>iptables</b> rules that spread traffic for a Service IP over its pods.'),
    step('Reload systemd', 'systemctl daemon-reload', 'Three new units.'),
    step('Enable the services', 'systemctl enable containerd kubelet kube-proxy', 'Start at boot.'),
    step('Start the services', 'systemctl start containerd kubelet kube-proxy',
      'In this order: runtime, then kubelet (which needs the runtime and, to register, the API server), then kube-proxy. A failure is explained by <code>systemctl status</code> / <code>journalctl -u NAME</code>: swap still on, a missing package, the wrong node certificate or a missing runtime each give a clear message.'),
    step('Leave node-0', 'exit', 'Back on the jumpbox.'),
    step('node-1: all of it in one command', nodePrep('node-1'),
      'Everything you just did on node-0, chained into a single remote command (steps separated by <code>;</code>). Read it from left to right and match each part with the steps above.'),
    step('Are the nodes registered?', 'ssh root@server "kubectl get nodes --kubeconfig admin.kubeconfig"',
      'Both nodes should be <b>Ready</b>. A node registers itself when its kubelet starts, using its kubeconfig; it becomes Ready once the runtime and the pod network are healthy. NotReady means something above is missing.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 10. remote access
  [
    step('Is the API reachable?', 'curl --cacert ca.crt https://server.kubernetes.local:6443/version',
      'Before configuring kubectl, check the raw HTTPS path works from the jumpbox: name resolution (hosts file), TLS (CA), and the API server answering.'),
    step('Add the cluster', 'kubectl config set-cluster kubernetes-the-hard-way --certificate-authority=ca.crt --embed-certs=true --server=https://server.kubernetes.local:6443',
      'Same idea as lab 5, but without <code>--kubeconfig</code>: kubectl writes to its <b>default file</b>, <code>~/.kube/config</code>. The server name must appear in the API server certificate\'s SANs, which it does.'),
    step('Add your credentials', 'kubectl config set-credentials admin --client-certificate=admin.crt --client-key=admin.key',
      'You are <code>admin</code>, in the group <code>system:masters</code>. This time the certificate is referenced by absolute path rather than embedded: fine on the machine that holds the files.'),
    step('Create the context', 'kubectl config set-context kubernetes-the-hard-way --cluster=kubernetes-the-hard-way --user=admin', 'Cluster + user under a name.'),
    step('Use the context', 'kubectl config use-context kubernetes-the-hard-way', 'Make it the default.'),
    step('Read your kubeconfig', 'cat ~/.kube/config',
      '<code>~</code> is your home directory. This is the file every kubectl command reads when you do not pass <code>--kubeconfig</code>.'),
    step('Client and server versions', 'kubectl version', 'Now the output includes the <b>Server Version</b>: the first proof that your client talks to your API server.'),
    step('List the nodes', 'kubectl get nodes',
      'Two Ready nodes, from your own jumpbox, without SSH. This is how you will use the cluster from now on.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 11. routes
  [
    step('The problem', 'cat machines.txt',
      'Each node gives its pods addresses from its own subnet: node-0 <code>10.200.0.0/24</code>, node-1 <code>10.200.1.0/24</code>. A pod on node-0 that talks to a pod on node-1 sends a packet to <code>10.200.1.x</code>; node-0 has no idea where that is. Kubernetes requires <b>every pod to reach every pod without NAT</b>, so the machines need <b>routes</b>: "to reach 10.200.1.0/24, send to node-1\'s IP". Cloud providers and overlay networks (Flannel, Calico) do this automatically; here we add them by hand.'),
    step('Look at the current routes', 'ssh root@server ip route',
      'Only the default gateway and the local network. Nothing about pod subnets.'),
    step('Read the values into variables', 'SERVER_IP=$(grep server machines.txt | cut -d " " -f 1)',
      'The same grep/cut trick: field 1 is the IP address. (Not needed for the routes below, but handy to see the pattern.)'),
    step('node-0 address', 'NODE_0_IP=$(grep node-0 machines.txt | cut -d " " -f 1)', 'Field 1: the IP.'),
    step('node-0 pod subnet', 'NODE_0_SUBNET=$(grep node-0 machines.txt | cut -d " " -f 4)', 'Field 4: the pod subnet.'),
    step('node-1 address', 'NODE_1_IP=$(grep node-1 machines.txt | cut -d " " -f 1)', 'Field 1 again.'),
    step('node-1 pod subnet', 'NODE_1_SUBNET=$(grep node-1 machines.txt | cut -d " " -f 4)', 'Field 4 again.'),
    step('Routes on the server', 'ssh root@server "ip route add ${NODE_0_SUBNET} via ${NODE_0_IP}; ip route add ${NODE_1_SUBNET} via ${NODE_1_IP}"',
      '<code>ip route add NETWORK via GATEWAY</code>: to reach each pod subnet, send packets to the node that owns it. The server needs both because the API server sometimes talks to pods (and to kubelets) directly.'),
    step('Route on node-0', 'ssh root@node-0 "ip route add ${NODE_1_SUBNET} via ${NODE_1_IP}"', 'node-0 already knows its own pods; it needs a way to node-1\'s.'),
    step('Route on node-1', 'ssh root@node-1 "ip route add ${NODE_0_SUBNET} via ${NODE_0_IP}"', 'And the reverse.'),
    step('Verify', 'ssh root@node-0 ip route',
      'The new line <code>10.200.1.0/24 via 10.240.0.21</code> is there. The smoke test will prove it: a Service reached through one node, backed by a pod on the other, only works with these routes.'),
  ],

  // ------------------------------------------------------------------------------------------------------------ 12. smoke test
  [
    step('Create a secret', 'kubectl create secret generic kubernetes-the-hard-way --from-literal="mykey=mydata"',
      'A <b>Secret</b> holds sensitive data. <code>--from-literal</code> sets a key and value inline. This one is just a test subject for the encryption you configured in lab 6.'),
    step('Look into etcd', "ssh root@server 'etcdctl get /registry/secrets/default/kubernetes-the-hard-way | hexdump -C'",
      'Kubernetes stores every object in etcd under <code>/registry/...</code>. This reads the raw bytes of your secret and shows them as a hex dump. <b>If encryption works</b> the value starts with <code>k8s:enc:aescbc:v1:key1</code> and you cannot read "mydata" in the ASCII column. If you see <code>mydata</code> in plain text, the API server did not use your encryption config.'),
    step('Create a deployment', 'kubectl create deployment nginx --image=nginx:latest',
      'A <b>Deployment</b> asks for pods running an image. Behind the scenes: the API server stores it, the controller manager creates a ReplicaSet and a pod, the scheduler picks a node, the kubelet there asks containerd to pull and run the image. Each component you installed has just done its part.'),
    step('Watch it start', 'kubectl get pods -l app=nginx',
      '<code>-l app=nginx</code> selects by <b>label</b>. Wait a few seconds and repeat until the status is <b>Running</b> (first <i>Pending</i>, then <i>ContainerCreating</i>). The pod\'s node is shown in <code>-o wide</code>.'),
    step('Remember the pod name', 'POD_NAME=$(kubectl get pods -l app=nginx -o jsonpath="{.items[0].metadata.name}")',
      '<code>-o jsonpath</code> extracts one field from the JSON the API returns. Here: the name of the first pod. Variables make the next three commands easy.'),
    step('Port forwarding', 'kubectl port-forward $POD_NAME 8080:80',
      'Maps local port 8080 to the pod\'s port 80 through the API server and the kubelet (which uses <b>socat</b> on the node). This works only if the RBAC rule from lab 8 and the socat package from lab 9 are in place. A real port-forward keeps running until you press Ctrl+C.'),
    step('Logs', 'kubectl logs $POD_NAME',
      'Again API server &rarr; kubelet: the kubelet reads the container log. Forbidden? Check lab 8\'s RBAC step.'),
    step('Exec', 'kubectl exec -ti $POD_NAME -- nginx -v',
      'Runs a command inside the container. <code>--</code> separates kubectl\'s flags from the command; <code>-ti</code> asks for an interactive terminal. nginx prints its version.'),
    step('Expose it', 'kubectl expose deployment nginx --port 80 --type NodePort',
      'A <b>Service</b> gives pods a stable address. <code>NodePort</code> additionally opens one port (30000-32767) on <b>every node</b>; kube-proxy forwards it to a pod. No cloud load balancer exists in this cluster, so NodePort is how you reach it from outside.'),
    step('Read the port', 'NODE_PORT=$(kubectl get svc nginx --output=jsonpath="{.spec.ports[0].nodePort}")', 'Another JSONPath query: the port Kubernetes picked.'),
    step('Find the pod\'s node', 'NODE_NAME=$(kubectl get pods -l app=nginx -o jsonpath="{.items[0].spec.nodeName}")', 'Which node runs the pod.'),
    step('Call it', 'curl -I http://${NODE_NAME}:${NODE_PORT}',
      'You should get <b>HTTP/1.1 200 OK</b> from nginx. Try the <i>other</i> node\'s name: it still works, because kube-proxy forwards across nodes using the routes from lab 11. Remove the routes and that call would hang. You have built, and understood, a working Kubernetes cluster.'),
  ],
];
